import json, pathlib
with open("data/iso27001-controls.json", "r", encoding="utf-8") as f:
    orig = json.load(f)
controls = orig["controls"]
desc_map = {}
desc_map["5.1"] = "Policies for information security: Topic-specific policies and high-level security policies shall be defined, approved by management, published, and communicated. Sourced from NIST SP 800-53 PL-1 (Program Planning) and PL-2 (System Security Plan), requiring periodic review, management approvals, and policy updates based on organizational or regulatory changes."
desc_map["5.2"] = "Information security roles and responsibilities: Assign roles and responsibilities to individuals and entities. Sourced from NIST SP 800-53 PS-2 (Position Categorization) and PM-3 (Information Security Resources), allocating security officer duties, system administrator roles, data custodians, and user responsibilities."
desc_map["5.3"] = "Segregation of duties: Segregate conflicting duties and areas of responsibility to minimize opportunities for unauthorized modification or abuse. Sourced from NIST SP 800-53 AC-5 (Separation of Duties), requiring two-person control for critical operations and split administrator/auditor access."
desc_map["5.4"] = "Management responsibilities: Management must enforce compliance with policies and procedures. Sourced from NIST SP 800-53 PL-4 (Rules of Behavior) and PS-8 (Personnel Compliance), ensuring supervisors monitor security obedience, training participation, and administer disciplinary actions."
desc_map["5.5"] = "Contact with authorities: Establish contact with law enforcement, regulators, and emergency teams. Sourced from NIST SP 800-53 IR-6 (Incident Reporting) and CP-2 (Contingency Plan), defining escalation paths and mandatory external reporting timelines."
desc_map["5.6"] = "Contact with special interest groups: Maintain relationships with professional security forums and groups. Sourced from NIST SP 800-53 PM-15 (Contacts with Security Groups), enabling sharing of threat info and best practices."
desc_map["5.7"] = "Threat intelligence: Threat intelligence feeds must be collected, analysed, and acted upon. Sourced from NIST SP 800-53 PM-16 (Threat Awareness) and SI-4 (System Monitoring), utilizing STIX/TAXII or ISAC data to adjust defenses."
desc_map["5.8"] = "Information security in project management: Integrate security into project lifecycle. Sourced from NIST SP 800-53 SA-3 (System Development Life Cycle) and SA-8 (Security Engineering Principles), conducting risk reviews at milestones."
desc_map["5.9"] = "Inventory of information and other associated assets: Maintain detailed inventory of hardware, software, and data. Sourced from NIST SP 800-53 CM-8 (Information System Component Inventory), tracking asset owners and configurations."
desc_map["5.10"] = "Acceptable use of information and other associated assets: Define acceptable use rules for assets. Sourced from NIST SP 800-53 PL-4 (Rules of Behavior) and AC-20 (Use of External Information Systems), requiring signed policy agreements."
desc_map["5.11"] = "Return of assets: All personnel return organization assets upon termination. Sourced from NIST SP 800-53 PS-4 (Personnel Termination) and PS-5 (Personnel Transfer), requiring checklist collection of devices."
desc_map["5.12"] = "Classification of information: Classify data based on confidentiality, integrity, availability. Sourced from NIST SP 800-53 RA-2 (Security Categorization), establishing public, internal, and confidential schema."
desc_map["5.13"] = "Labelling of information: Label information assets dynamically or manually. Sourced from NIST SP 800-53 MP-3 (Media Marking), adding headers, footers, or metadata tags matching categorization."
desc_map["5.14"] = "Information transfer: Secure data transit via email, network, or files. Sourced from NIST SP 800-53 SC-8 (Transmission Confidentiality and Integrity) and MP-5 (Media Transport), enforcing TLS or AES encryption."
desc_map["5.15"] = "Access control: Restrict logical access to systems and applications. Sourced from NIST SP 800-53 AC-2 (Account Management), AC-3 (Access Enforcement), and AC-6 (Least Privilege), configuring authorization roles."
desc_map["5.16"] = "Identity management: Establish unique user and service account identities. Sourced from NIST SP 800-53 IA-2 (Identification and Authentication), managing provisioning, movers, and leavers lifecycles."
desc_map["5.17"] = "Authentication information: Enforce password complexity, length, hashing, and rotation. Sourced from NIST SP 800-53 IA-5 (Authenticator Management), hashing passwords with bcrypt/argon2."
desc_map["5.18"] = "Access rights: Provision, review, modify, and revoke access rights. Sourced from NIST SP 800-53 AC-2 (Account Management) and AC-2(1) (Access Reviews), scheduling quarterly access audits."
desc_map["5.19"] = "Information security in supplier relationships: Formulate supplier risk programs. Sourced from NIST SP 800-53 SA-9 (External System Services) and SR-3 (Supply Chain Acquisition), performing third-party reviews."
desc_map["5.20"] = "Addressing information security within supplier agreements: Incorporate security terms into supplier contracts. Sourced from NIST SP 800-53 SA-9 (External System Services), specifying notification SLA."
desc_map["5.21"] = "Managing information security in the ICT supply chain: Manage hardware and software supply risks. Sourced from NIST SP 800-53 SR-2 (SCRM Plan) and SR-5 (Acquisition Provenance), enforcing SBOM checks."
desc_map["5.22"] = "Monitoring review and change management of supplier services: Perform audits and reviews of suppliers. Sourced from NIST SP 800-53 SA-9 (External System Services) and SR-6 (Supplier Auditing), examining SOC2."
desc_map["5.23"] = "Information security for use of cloud services: Implement secure cloud usage. Sourced from NIST SP 800-53 SA-9 (External System Services) and AC-20 (External Systems), defining cloud control scopes."
desc_map["5.24"] = "Information security incident management planning and preparation: Incident management processes, roles, and responsibilities. Sourced from NIST SP 800-53 IR-8 (Incident Response Plan) and IR-2 (Incident Response Training)."
desc_map["5.25"] = "Assessment and decision on information security events: Triage security logs to find incidents. Sourced from NIST SP 800-53 IR-4 (Incident Handling) and IR-5 (Incident Monitoring), determining breach thresholds."
desc_map["5.26"] = "Response to information security incidents: Implement containment and eradication. Sourced from NIST SP 800-53 IR-4 (Incident Handling), IR-4(1) (Incident Response Coordination), and IR-4(2) (Incident Containment)."
desc_map["5.27"] = "Learning from information security incidents: Lessons learned reviews. Sourced from NIST SP 800-53 IR-4(4) (Information Leakage Mitigation) and PM-28 (Lessons Learned Program), improving response plans."
desc_map["5.28"] = "Collection of evidence: Maintain chain of custody for logs and files. Sourced from NIST SP 800-53 IR-4 (Incident Handling) and AU-10 (Non-repudiation), using forensically sound write-once media."
desc_map["5.29"] = "Information security during disruption: Maintain controls during business continuity. Sourced from NIST SP 800-53 CP-2 (Contingency Plan) and CP-10 (System Recovery and Reconstitution), enforcing recovery rules."
desc_map["5.30"] = "ICT readiness for business continuity: Redundancy and recovery time/point objectives. Sourced from NIST SP 800-53 CP-2 (Contingency Plan) and CP-9 (System Backup), specifying RTO and RPO metrics."
desc_map["5.31"] = "Legal statutory regulatory and contractual requirements: Record compliance obligations. Sourced from NIST SP 800-53 PM-26 (Compliance Management) and PM-31 (Compliance Audits), tracking regulations."
desc_map["5.32"] = "Intellectual property rights: Enforce licensing and patent rights. Sourced from NIST SP 800-53 SA-4 (Acquisition Process) and CM-10 (Software Usage Restrictions), preventing pirated copy deployment."
desc_map["5.33"] = "Protection of records: Secure log files and archives. Sourced from NIST SP 800-53 AU-9 (Protection of Audit Information) and MP-4 (Media Storage), employing GPO file restrictions."
desc_map["5.34"] = "Privacy and protection of PII: Protect personally identifiable information. Sourced from NIST SP 800-53 PT-2 (Privacy Authority) and PT-3 (PII Processing Categories), enforcing minimization."
desc_map["5.35"] = "Independent review of information security: Schedule independent security audits. Sourced from NIST SP 800-53 CA-2 (Control Assessments) and PM-30 (Independent Assessments), hiring external auditors."
desc_map["5.36"] = "Compliance with policies rules and standards for information security: Perform compliance checks. Sourced from NIST SP 800-53 CA-7 (Continuous Monitoring) and PM-14 (Compliance Reviews), using vulnerability scanning."
desc_map["5.37"] = "Documented operating procedures: Standard runbooks and playbooks. Sourced from NIST SP 800-53 PL-2 (System Security Plan) and CM-9 (Configuration Management Plan), storing procedure files in repository."
desc_map["6.1"] = "Screening: Background verification checks on all candidates. Sourced from NIST SP 800-53 PS-3 (Personnel Screening), conducting criminal record and credit checks prior to hiring."
desc_map["6.2"] = "Terms and conditions of employment: Employment contracts. Sourced from NIST SP 800-53 PS-6 (Access Agreements) and PL-4 (Rules of Behavior), enforcing signed confidentiality agreements."
desc_map["6.3"] = "Information security awareness education and training: Mandatory phishing and general awareness training. Sourced from NIST SP 800-53 AT-2 (Security Awareness Training) and AT-3 (Role-based Security Training)."
desc_map["6.4"] = "Disciplinary process: Discipline rules for security breaches. Sourced from NIST SP 800-53 PS-8 (Personnel Compliance) and PS-8(1) (Disciplinary Program), defining action types."
desc_map["6.5"] = "Responsibilities after termination or change of employment: Offboarding tasks. Sourced from NIST SP 800-53 PS-4 (Personnel Termination) and PS-5 (Personnel Transfer), disabling directory access."
desc_map["6.6"] = "Confidentiality or non-disclosure agreements: Enforce NDAs. Sourced from NIST SP 800-53 PS-6 (Access Agreements), requiring legal-approved templates for contractors."
desc_map["6.7"] = "Remote working: Secure remote locations. Sourced from NIST SP 800-53 AC-17 (Remote Access) and AC-17(1) (Monitoring Remote Access), requiring endpoint VPN."
desc_map["6.8"] = "Information security event reporting: Suspicious activity reporting. Sourced from NIST SP 800-53 IR-6 (Incident Reporting) and IR-6(1) (Incident Reporting Escalation), setting up helpdesk tag."
desc_map["7.1"] = "Physical security perimeters: Perimeter walls and doors. Sourced from NIST SP 800-53 PE-2 (Physical Access Authorizations) and PE-3 (Physical Access Control), installing fences and alarms."
desc_map["7.2"] = "Physical entry: Badge and biometrics validation. Sourced from NIST SP 800-53 PE-3 (Physical Access Control) and PE-3(1) (Key Management), requiring escorts for visitors."
desc_map["7.3"] = "Securing offices rooms and facilities: Lock internal spaces. Sourced from NIST SP 800-53 PE-3 (Physical Access Control) and PE-4 (Access Control for Transmission Medium), locking network closets."
desc_map["7.4"] = "Physical security monitoring: Install intrusion detectors. Sourced from NIST SP 800-53 PE-6 (Monitoring Physical Access) and PE-6(1) (Physical Security Alarms), configuring CCTV."
desc_map["7.5"] = "Protecting against physical and environmental threats: Safeguard against disaster. Sourced from NIST SP 800-53 PE-13 (Fire Protection) and PE-14 (Temperature and Humidity Controls)."
desc_map["7.6"] = "Working in secure areas: Enforce rules inside server rooms. Sourced from NIST SP 800-53 PE-3 (Physical Access Control) and PE-18 (Location of Information System Components), banning cell phones."
desc_map["7.7"] = "Clear desk and clear screen: Clean desk GPO policies. Sourced from NIST SP 800-53 PE-3 (Physical Access Control) and AC-11 (Device Lock), enforcing 15-minute locks."
desc_map["7.8"] = "Equipment siting and protection: Safe server rack installation. Sourced from NIST SP 800-53 PE-18 (Location of Information System Components), avoiding water pipe lines."
desc_map["7.9"] = "Security of assets off-premises: Laptops offsite. Sourced from NIST SP 800-53 MP-4 (Media Storage) and AC-20 (External Systems), requiring full-disk BitLocker encryption."
desc_map["7.10"] = "Storage media: Lifecycle transport of USBs. Sourced from NIST SP 800-53 MP-4 (Media Storage) and MP-5 (Media Transport), using locked courier cases."
desc_map["7.11"] = "Supporting utilities: Emergency generators. Sourced from NIST SP 800-53 PE-11 (Emergency Power) and PE-12 (Emergency Shutoff), scheduling monthly UPS tests."
desc_map["7.12"] = "Cabling security: Enclosed cable trays. Sourced from NIST SP 800-53 PE-4 (Access Control for Transmission Medium), locking server cabling pathways."
desc_map["7.13"] = "Equipment maintenance: System hardware maintenance. Sourced from NIST SP 800-53 MA-2 (Controlled Maintenance) and MA-4 (Local Maintenance), logging technician visits."
desc_map["7.14"] = "Secure disposal or re-use of equipment: Wipe storage before disposal. Sourced from NIST SP 800-53 MP-6 (Media Sanitization), requiring cross-cut shredders or degaussers."
desc_map["8.1"] = "User endpoint devices: Endpoints laptops MDM policies. Sourced from NIST SP 800-53 AC-19 (Access Control for Mobile Devices) and CM-7 (Least Functionality), enforcing screen timeout."
desc_map["8.2"] = "Privileged access rights: Restrict administrative rights. Sourced from NIST SP 800-53 AC-6 (Least Privilege) and AC-2(2) (Privileged Accounts), using PAM portal logging."
desc_map["8.3"] = "Information access restriction: Apply read/write constraints. Sourced from NIST SP 800-53 AC-3 (Access Enforcement) and AC-4 (Information Flow Enforcement), using directory ACLs."
desc_map["8.4"] = "Access to source code: Secure code repositories. Sourced from NIST SP 800-53 SA-8 (Security Engineering Principles) and SA-11 (Developer Security), restricting write access."
desc_map["8.5"] = "Secure authentication: Enforce multi-factor authentication. Sourced from NIST SP 800-53 IA-2(1) (MFA) and IA-8 (Identification and Authentication Non-Organizational Users)."
desc_map["8.6"] = "Capacity management: Resource utilization monitoring. Sourced from NIST SP 800-53 AU-4 (Audit Storage Capacity) and SC-6 (Resource Availability), scaling storage clusters."
desc_map["8.7"] = "Protection against malware: Endpoint EDR scanning. Sourced from NIST SP 800-53 SI-3 (Malicious Code Protection), configuring automated real-time signature definition downloads."
desc_map["8.8"] = "Management of technical vulnerabilities: Automated vulnerability scans and patches. Sourced from NIST SP 800-53 RA-5 (Vulnerability Monitoring) and SI-2 (Flaw Remediation)."
desc_map["8.9"] = "Configuration management: Secure configuration baseline. Sourced from NIST SP 800-53 CM-2 (Baseline Configuration) and CM-3 (Configuration Change Control), auditing changes."
desc_map["8.10"] = "Information deletion: Secure media sanitization and information deletion policies. Sourced from NIST SP 800-53 MP-6 (Media Sanitization) and SI-12 (Information Management and Retention), requiring secure overwriting, degaussing, or physical destruction of media when no longer required, in accordance with retention schedules and legal obligations. Automated deletion scripts, lifecycle rules, and destruction certificates are logged."
desc_map["8.11"] = "Data masking: Anonymize or mask data. Sourced from NIST SP 800-53 PT-2 (Authority to Process) and PT-3 (Personally Identifiable Information Processing Categories)."
desc_map["8.12"] = "Data leakage prevention: Block data egress. Sourced from NIST SP 800-53 SC-7(10) (Preventing Exfiltration) and SI-4 (System Monitoring), applying SWG and DLP rules."
desc_map["8.13"] = "Information backup: Back up server configurations and user data. Sourced from NIST SP 800-53 CP-9 (System Backup) and CP-9(1) (Testing Recovery), testing restore exercises."
desc_map["8.14"] = "Redundancy of information processing facilities: Redundant servers and zones. Sourced from NIST SP 800-53 CP-2(3) (Alternate Processing Site) and SC-6 (Resource Availability)."
desc_map["8.15"] = "Logging: Generate audit logs. Sourced from NIST SP 800-53 AU-2 (Audit Events) and AU-6 (Audit Review), retaining logs in centralized SIEM and configuring alerts."
desc_map["8.16"] = "Monitoring activities: Monitor networks and applications. Sourced from NIST SP 800-53 SI-4 (System Monitoring) and SI-4(5) (System Monitoring | Analyzer Receivers), analyzing events."
desc_map["8.17"] = "Clock synchronization: NTP time synchronization. Sourced from NIST SP 800-53 AU-8 (Time Stamps), mapping Stratum 1 time server clocks to prevent log timestamp mismatches."
desc_map["8.18"] = "Use of privileged utility programs: Restrict dangerous diagnostic tools. Sourced from NIST SP 800-53 AC-6 (Least Privilege) and CM-7 (Least Functionality), whitelisting programs."
desc_map["8.19"] = "Installation of software on operational systems: Restrict user install rights. Sourced from NIST SP 800-53 CM-11 (User-installed Software), enforcing administrator privileges constraints."
desc_map["8.20"] = "Network security: Hardened network firewalls and switches. Sourced from NIST SP 800-53 SC-7 (Boundary Protection) and SC-7(3) (Access Points), monitoring ingress and egress."
desc_map["8.21"] = "Security of network services: Secure cloud network services. Sourced from NIST SP 800-53 SC-7 (Boundary Protection) and SA-9 (External System Services), enforcing TLS."
desc_map["8.22"] = "Segregation of networks: Divide network zones. Sourced from NIST SP 800-53 SC-7(21) (Isolation of Information Systems) and SC-39 (Process Isolation), separating guest Wi-Fi."
desc_map["8.23"] = "Web filtering: Limit access to malicious domains. Sourced from NIST SP 800-53 SC-7(11) (Restrict External Web Service) and SI-4 (System Monitoring), applying SWG gateway policies."
desc_map["8.24"] = "Use of cryptography: Define encryption standards. Sourced from NIST SP 800-53 SC-13 (Cryptographic Protection) and IA-5(1) (Password Hashing), requiring AES-256 and FIPS compliance."
desc_map["8.25"] = "Secure development life cycle: Integrate security into developer workflows. Sourced from NIST SP 800-53 SA-3 (System Development Life Cycle) and SA-8 (Security Principles)."
desc_map["8.26"] = "Application security requirements: Validate software requirements. Sourced from NIST SP 800-53 SA-4 (Acquisition Process) and SA-8 (Security Engineering Principles)."
desc_map["8.27"] = "Secure system architecture and engineering principles: Deploy zero trust patterns. Sourced from NIST SP 800-53 SA-8 (Security Engineering Principles), minimizing attack vectors."
desc_map["8.28"] = "Secure coding: Static application security testing (SAST). Sourced from NIST SP 800-53 SA-11 (Developer Security Testing) and SI-16 (Memory Protection), checking code arrays."
desc_map["8.29"] = "Security testing in development and acceptance: Manual code audits and DAST. Sourced from NIST SP 800-53 SA-11 (Developer Security Testing) and CA-2 (Control Assessments)."
desc_map["8.30"] = "Outsourced development: Monitor third-party code. Sourced from NIST SP 800-53 SA-9 (External System Services) and SA-11 (Developer Security Testing), enforcing NDA controls."
desc_map["8.31"] = "Separation of development test and production environments: Restrict developer access to live environments. Sourced from NIST SP 800-53 AC-6 (Least Privilege) and CM-2 (Baseline)."
desc_map["8.32"] = "Change management: Record changes to infrastructure. Sourced from NIST SP 800-53 CM-3 (Configuration Change Control) and CM-4 (Security Impact Analysis), requiring CAB sign-off."
desc_map["8.33"] = "Test information: Mask production databases before test. Sourced from NIST SP 800-53 PT-2 (Authority to Process) and PT-3 (PII Processing Categories), using synthetic data."
desc_map["8.34"] = "Protection of information systems during audit testing: Agree audit tools and scope. Sourced from NIST SP 800-53 CA-2 (Control Assessments) and CA-7 (Continuous Monitoring)."
for c in controls:
    cid = c["id"]
    title = c["title"]
    desc = desc_map.get(cid, c.get("description", ""))
    c["description"] = desc
    c["text"] = desc
    c["section_heading"] = f"{cid} {title}"
out = {
    "_source": "NIST SP 800-53 Rev 5 to ISO 27001:2022 public-domain cross-reference mapping. NOT verbatim ISO 27001:2022 text.",
    "controls": controls
}
pathlib.Path("data/iso27001-controls-enriched.json").write_text(json.dumps(out, indent=2, ensure_ascii=False), encoding="utf-8")
print("Enriched controls JSON written successfully!")
